from PIL import Image
import numpy as np

# Open the image
image = Image.open('ctf_files/short-circuit.jpg')

# Convert to grayscale
gray = image.convert('L')

# Convert to binary (threshold at 128)
binary = np.array(gray) > 128

# Helper functions
def chunks(lst, n):
    for i in range(0, len(lst), n):
        yield lst[i:i+n]

def binary_to_ascii(binary_str):
    try:
        n = int(binary_str, 2)
        return chr(n) if 32 <= n <= 126 else None
    except:
        return None

# Extract horizontal lines
height, width = binary.astype(int).shape
print(f"Image dimensions: {width}x{height}")

# Try different line widths
line_widths = [7, 8, 14, 16, 32, 64]

for row in range(height):
    line = ''.join(['1' if x else '0' for x in binary[row]])
    if '1' in line:  # Only process non-empty lines
        print(f"\nRow {row}:")
        print("Binary:", line)

        # Try 8-bit chunks
        bytes_msb = [''.join(x) for x in chunks(line, 8)]
        print("\n8-bit chunks (MSB):")
        ascii_chars = ''
        for byte in bytes_msb:
            if len(byte) == 8:
                char = binary_to_ascii(byte)
                if char:
                    ascii_chars += char
        if ascii_chars:
            print("ASCII:", ascii_chars)

        # Try LSB ordering
        bytes_lsb = [''.join(reversed(x)) for x in chunks(line, 8)]
        print("\n8-bit chunks (LSB):")
        ascii_chars = ''
        for byte in bytes_lsb:
            if len(byte) == 8:
                char = binary_to_ascii(byte)
                if char:
                    ascii_chars += char
        if ascii_chars:
            print("ASCII:", ascii_chars)

        # Try different widths for line breaking
        for w in line_widths:
            if len(line) >= w:
                print(f"\nWidth {w}:")
                for chunk in chunks(line, w):
                    print(chunk)
